import React, { useState, useRef, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { Heart, User, Menu, X, ChevronDown } from 'lucide-react';
import styles from './Navbar.module.css';

const NAV_ITEMS = [
  { label: 'Buy',        to: '/search?listingType=Sell' },
  { label: 'Rent',       to: '/search?listingType=Rent' },
  { label: 'Sell',       to: '/post-property'           },
  { label: 'Services',   to: '/search'                  },
];

export default function Navbar() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [menuOpen,     setMenuOpen]     = useState(false);
  const [userDropOpen, setUserDropOpen] = useState(false);
  const dropRef = useRef(null);

  // Close user dropdown when clicking outside
  useEffect(() => {
    const handler = (e) => {
      if (dropRef.current && !dropRef.current.contains(e.target)) {
        setUserDropOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  return (
    <header className={styles.header}>
      <div className={styles.inner}>

        {/* ── Logo ──────────────────────────────────────── */}
        <Link to="/" className={styles.brand}>
          <div className={styles.logoIconWrap}>
            <span className={styles.logoIcon}>⬡</span>
          </div>
          <span className={styles.logoText}>ProBridge</span>
        </Link>

        {/* ── Desktop Nav Links ──────────────────────────── */}
        <nav className={styles.nav}>
          {NAV_ITEMS.map(item => (
            <Link key={item.label} to={item.to} className={styles.navLink}>
              {item.label}
              <ChevronDown size={13} className={styles.navChevron} />
            </Link>
          ))}
        </nav>

        {/* ── Right Actions ──────────────────────────────── */}
        <div className={styles.actions}>
          {/* Guest / User */}
          <div className={styles.userWrap} ref={dropRef}>
            <button
              className={styles.userBtn}
              onClick={() => setUserDropOpen(o => !o)}
            >
              {user?.photo
                ? <img src={user.photo} alt={user.name} className={styles.userAvatar} />
                : <User size={16} className={styles.userIcon} />
              }
              <span className={styles.userName}>
                {user ? user.name.split(' ')[0] : 'Guest'}
              </span>
              <ChevronDown size={13} />
            </button>

            {userDropOpen && (
              <div className={styles.userDrop}>
                {user ? (
                  <>
                    <div className={styles.userDropName}>{user.name}</div>
                    <div className={styles.userDropEmail}>{user.email}</div>
                    <div className={styles.userDropDivider} />
                    <Link to="/account"            className={styles.userDropItem} onClick={() => setUserDropOpen(false)}>My Account</Link>
                    <Link to="/account?tab=listings" className={styles.userDropItem} onClick={() => setUserDropOpen(false)}>My Listings</Link>
                    <Link to="/saved"              className={styles.userDropItem} onClick={() => setUserDropOpen(false)}>Shortlisted</Link>
                    <div className={styles.userDropDivider} />
                    <button
                      className={`${styles.userDropItem} ${styles.userDropLogout}`}
                      onClick={() => { logout(); setUserDropOpen(false); navigate('/'); }}
                    >Sign Out</button>
                  </>
                ) : (
                  <>
                    <Link to="/login"    className={styles.userDropItem} onClick={() => setUserDropOpen(false)}>Login</Link>
                    <Link to="/register" className={styles.userDropItem} onClick={() => setUserDropOpen(false)}>Register</Link>
                  </>
                )}
              </div>
            )}
          </div>

          {/* Shortlisted / Saved */}
          <Link to="/saved" className={styles.shortlistedBtn}>
            <Heart size={15} />
            <span>Shortlisted</span>
          </Link>

          {/* Post Property */}
          <Link to="/post-property" className={styles.postBtn}>
            <span className={styles.postBtnPlus}>✦</span>
            Post Property
          </Link>

          {/* Hamburger */}
          <button
            className={styles.hamburger}
            onClick={() => setMenuOpen(o => !o)}
            aria-label="Menu"
          >
            {menuOpen ? <X size={22} /> : <Menu size={22} />}
          </button>
        </div>
      </div>

      {/* ── Mobile Menu ────────────────────────────────── */}
      {menuOpen && (
        <div className={styles.mobileMenu}>
          {NAV_ITEMS.map(item => (
            <Link
              key={item.label}
              to={item.to}
              className={styles.mobileLink}
              onClick={() => setMenuOpen(false)}
            >{item.label}</Link>
          ))}
          <div className={styles.mobileDivider} />
          {user ? (
            <>
              <Link to="/saved"   className={styles.mobileLink} onClick={() => setMenuOpen(false)}>Shortlisted</Link>
              <Link to="/account" className={styles.mobileLink} onClick={() => setMenuOpen(false)}>My Account</Link>
              <button className={styles.mobileLink} onClick={() => { logout(); setMenuOpen(false); navigate('/'); }}>Sign Out</button>
            </>
          ) : (
            <>
              <Link to="/login"    className={styles.mobileLink} onClick={() => setMenuOpen(false)}>Login</Link>
              <Link to="/register" className={styles.mobileLink} onClick={() => setMenuOpen(false)}>Register</Link>
            </>
          )}
          <Link to="/post-property" className={styles.mobilePostBtn} onClick={() => setMenuOpen(false)}>
            + Post Property Free
          </Link>
        </div>
      )}
    </header>
  );
}
